pub struct PetDeleteMany<'repo, 'ctx> {
    repo: &'repo PetRepository<'ctx>,
    hooks: Vec<std::sync::Arc<dyn roze_orm::OperationMiddleware<Self, u64, anyhow::Error> + 'repo>>,
    predicates: Vec<PetPredicate>,
}

impl<'repo, 'ctx> PetDeleteMany<'repo, 'ctx> {
    pub fn new(repo: &'repo PetRepository<'ctx>) -> Self {
        Self {
            repo,
            hooks: Vec::new(),
            predicates: Vec::new(),
        }
    }

    pub fn where_(mut self, predicate: PetPredicate) -> Self {
        self.predicates.push(predicate);
        self
    }

    pub fn where_all<I>(mut self, predicates: I) -> Self
    where
        I: IntoIterator<Item = PetPredicate>,
    {
        self.predicates.extend(predicates);
        self
    }

    pub fn where_any<I>(mut self, predicates: I) -> Self
    where
        I: IntoIterator<Item = PetPredicate>,
    {
        let predicates = predicates.into_iter().collect::<Vec<_>>();
        if !predicates.is_empty() {
            self.predicates.push(PetPredicate::Or(predicates));
        }
        self
    }

    pub fn where_not(mut self, predicate: PetPredicate) -> Self {
        self.predicates.push(PetPredicate::Not(Box::new(predicate)));
        self
    }

    pub fn where_none<I>(mut self, predicates: I) -> Self
    where
        I: IntoIterator<Item = PetPredicate>,
    {
        let predicates = predicates.into_iter().collect::<Vec<_>>();
        if !predicates.is_empty() {
            self.predicates
                .push(PetPredicate::Not(Box::new(PetPredicate::Or(predicates))));
        }
        self
    }

    pub fn hook<H>(mut self, hook: H) -> Self
    where
        H: roze_orm::OperationMiddleware<Self, u64, anyhow::Error> + 'repo,
    {
        self.hooks.push(std::sync::Arc::new(hook));
        self
    }

    pub fn policy<I, D>(mut self, rules: I, deny_by_default: D) -> Self
    where
        I: IntoIterator<
            Item = std::sync::Arc<dyn roze_orm::Policy<Self, Error = anyhow::Error> + 'repo>,
        >,
        D: Fn() -> anyhow::Error + Send + Sync + 'repo,
    {
        self.hooks
            .push(std::sync::Arc::new(roze_orm::PolicyMiddleware::new(
                rules,
                deny_by_default,
            )));
        self
    }

    pub fn mixin<M>(self, mixin: M) -> Self
    where
        M: roze_orm::OperationMixin<Self>,
    {
        mixin.apply(self)
    }

    pub async fn exec(mut self) -> anyhow::Result<u64> {
        let hooks = std::mem::take(&mut self.hooks);
        roze_orm::execute_chain(&PetDeleteManyTerminal, &hooks, self).await
    }

    async fn exec_unhooked(self) -> anyhow::Result<u64> {
        let mut query = self.repo.query();
        for predicate in &self.predicates {
            query = query.where_(predicate.clone());
        }
        let items = query.all().await?;
        let mut rows_affected = 0u64;
        for item in items {
            let result = self.repo.delete_one(item.id).exec().await?;
            rows_affected += result.rows_affected;
        }
        Ok(rows_affected)
    }
}

struct PetDeleteManyTerminal;
impl<'repo, 'ctx> roze_orm::Operation<PetDeleteMany<'repo, 'ctx>, u64, anyhow::Error>
    for PetDeleteManyTerminal
{
    fn call<'a>(
        &'a self,
        mutation: PetDeleteMany<'repo, 'ctx>,
    ) -> roze_orm::OperationFuture<'a, u64, anyhow::Error>
    where
        PetDeleteMany<'repo, 'ctx>: 'a,
        u64: 'a,
        anyhow::Error: 'a,
    {
        Box::pin(mutation.exec_unhooked())
    }
}

/// Reusable schema/client mutation hook provider.
/// Providers are applied in registration order; hooks they add are outermost before hooks added directly to a builder.
pub trait PetMutationHooks: Send + Sync {
    fn create<'repo, 'ctx>(&self, mutation: PetCreate<'repo, 'ctx>) -> PetCreate<'repo, 'ctx> {
        mutation
    }
    fn update_one<'repo, 'ctx>(&self, mutation: PetUpdate<'repo, 'ctx>) -> PetUpdate<'repo, 'ctx> {
        mutation
    }
    fn delete_one<'repo, 'ctx>(&self, mutation: PetDelete<'repo, 'ctx>) -> PetDelete<'repo, 'ctx> {
        mutation
    }
    fn update_many<'repo, 'ctx>(
        &self,
        mutation: PetUpdateMany<'repo, 'ctx>,
    ) -> PetUpdateMany<'repo, 'ctx> {
        mutation
    }
    fn delete_many<'repo, 'ctx>(
        &self,
        mutation: PetDeleteMany<'repo, 'ctx>,
    ) -> PetDeleteMany<'repo, 'ctx> {
        mutation
    }
}

pub fn escape_like_pattern(value: &str) -> String {
    let mut escaped = String::with_capacity(value.len());
    for ch in value.chars() {
        match ch {
            '\\' | '%' | '_' => {
                escaped.push('\\');
                escaped.push(ch);
            }
            _ => escaped.push(ch),
        }
    }
    escaped
}

pub fn contains_like_pattern(value: &str) -> String {
    format!("%{}%", escape_like_pattern(value))
}

pub struct PetRepository<'a> {
    ctx: &'a ServiceContext,
    transaction: Option<&'a DatabaseTransaction>,
    pending_invalidations: Option<&'a std::sync::Mutex<Vec<String>>>,
    mutation_hooks: Vec<&'a dyn PetMutationHooks>,
}

impl<'a> PetRepository<'a> {
    pub fn new(ctx: &'a ServiceContext) -> Self {
        Self {
            ctx,
            transaction: None,
            pending_invalidations: None,
            mutation_hooks: Vec::new(),
        }
    }

    pub(crate) fn new_in_transaction(
        ctx: &'a ServiceContext,
        transaction: &'a DatabaseTransaction,
        pending_invalidations: &'a std::sync::Mutex<Vec<String>>,
    ) -> Self {
        Self {
            ctx,
            transaction: Some(transaction),
            pending_invalidations: Some(pending_invalidations),
            mutation_hooks: Vec::new(),
        }
    }

    pub fn with_mutation_hooks(mut self, hooks: &'a dyn PetMutationHooks) -> Self {
        self.mutation_hooks.push(hooks);
        self
    }

    fn read_database(&self) -> anyhow::Result<&DatabaseConnection> {
        self.ctx.read_db()
    }

    fn write_database(&self) -> anyhow::Result<&DatabaseConnection> {
        self.ctx.write_db()
    }

    fn read_db(&self) -> anyhow::Result<ModelConnection<'_>> {
        if let Some(transaction) = self.transaction {
            Ok(ModelConnection::Transaction(transaction))
        } else {
            Ok(ModelConnection::Database(self.read_database()?))
        }
    }

    fn write_db(&self) -> anyhow::Result<ModelConnection<'_>> {
        if let Some(transaction) = self.transaction {
            Ok(ModelConnection::Transaction(transaction))
        } else {
            Ok(ModelConnection::Database(self.write_database()?))
        }
    }

    fn read_db_from(&self, source: roze_orm::ReadSource) -> anyhow::Result<ModelConnection<'_>> {
        match source {
            roze_orm::ReadSource::Replica => self.read_db(),
            roze_orm::ReadSource::Primary => self.write_db(),
        }
    }

    pub async fn transaction<F, T>(&self, func: F) -> Result<T, DbErr>
    where
        F: for<'tx> FnOnce(
                &'tx DatabaseTransaction,
            ) -> std::pin::Pin<
                Box<dyn std::future::Future<Output = Result<T, DbErr>> + Send + 'tx>,
            > + Send,
        T: Send,
    {
        let db = self
            .write_database()
            .map_err(|err| DbErr::Custom(err.to_string()))?;
        tracing::debug!(
            backend = "sea_orm",
            phase = "begin",
            "model transaction phase"
        );
        let result = db
            .transaction::<_, T, DbErr>(func)
            .await
            .map_err(|err| match err {
                TransactionError::Connection(err) | TransactionError::Transaction(err) => err,
            });
        tracing::debug!(
            backend = "sea_orm",
            phase = if result.is_ok() { "commit" } else { "rollback" },
            "model transaction phase"
        );
        result
    }

    pub fn table_name() -> &'static str {
        "pets"
    }

    pub async fn seed_fixtures(&self, count: u64) -> anyhow::Result<Vec<Model>> {
        let mut seeded = Vec::with_capacity(count as usize);
        for index in 0..count {
            seeded.push(self.insert(Model::fixture(index)).await?);
        }
        Ok(seeded)
    }

    pub fn create(&self) -> PetCreate<'_, 'a> {
        self.mutation_hooks
            .iter()
            .fold(PetCreate::new(self), |mutation, hooks| {
                hooks.create(mutation)
            })
    }

    pub fn update_one(&self, id: i64) -> PetUpdate<'_, 'a> {
        self.mutation_hooks
            .iter()
            .fold(PetUpdate::new(self, id), |mutation, hooks| {
                hooks.update_one(mutation)
            })
    }

    pub fn delete_one(&self, id: i64) -> PetDelete<'_, 'a> {
        self.mutation_hooks
            .iter()
            .fold(PetDelete::new(self, id), |mutation, hooks| {
                hooks.delete_one(mutation)
            })
    }

    pub fn update_many(&self) -> PetUpdateMany<'_, 'a> {
        self.mutation_hooks
            .iter()
            .fold(PetUpdateMany::new(self), |mutation, hooks| {
                hooks.update_many(mutation)
            })
    }

    pub fn update_where(&self) -> PetUpdateMany<'_, 'a> {
        self.update_many()
    }

    pub fn delete_many(&self) -> PetDeleteMany<'_, 'a> {
        self.mutation_hooks
            .iter()
            .fold(PetDeleteMany::new(self), |mutation, hooks| {
                hooks.delete_many(mutation)
            })
    }

    pub fn query(&self) -> PetQuery<'_, 'a> {
        PetQuery::new(self)
    }

    pub async fn count(&self) -> anyhow::Result<u64> {
        self.query().count().await
    }

    pub async fn list_page(&self, page: u64, page_size: u64) -> anyhow::Result<PetPage> {
        self.query().paginate(page, page_size).page().await
    }

    pub async fn find_by_id(&self, id: i64) -> anyhow::Result<Option<Model>> {
        let db = self.read_db()?;
        Ok(Entity::find_by_id(id).one(&db).await?)
    }

    pub async fn find_by_id_primary(&self, id: i64) -> anyhow::Result<Option<Model>> {
        let db = self.write_db()?;
        Ok(Entity::find_by_id(id).one(&db).await?)
    }

    pub async fn list(&self) -> anyhow::Result<Vec<Model>> {
        let db = self.read_db()?;
        let select = Entity::find();
        Ok(select.all(&db).await?)
    }

    pub async fn insert(&self, model: Model) -> anyhow::Result<Model> {
        let db = self.write_db()?;
        let active: ActiveModel = model.into_active_model();
        let inserted = active.insert(&db).await?;
        Ok(inserted)
    }

    pub async fn upsert(&self, model: Model) -> anyhow::Result<Model> {
        let db = self.write_db()?;
        let active: ActiveModel = model.into_active_model();
        let saved = Entity::insert(active)
            .on_conflict(
                OnConflict::columns([Column::Id])
                    .update_columns([Column::OwnerId, Column::Name, Column::Species])
                    .to_owned(),
            )
            .exec_with_returning(&db)
            .await?;
        Ok(saved)
    }

    pub async fn insert_many(&self, models: Vec<Model>) -> anyhow::Result<()> {
        if models.is_empty() {
            return Ok(());
        }
        let db = self.write_db()?;
        let active_models = models
            .into_iter()
            .map(IntoActiveModel::into_active_model)
            .collect::<Vec<_>>();
        Entity::insert_many(active_models).exec(&db).await?;
        Ok(())
    }

    pub async fn delete_many_by_ids(&self, ids: Vec<i64>) -> anyhow::Result<DeleteResult> {
        if ids.is_empty() {
            return Ok(DeleteResult { rows_affected: 0 });
        }
        let db = self.write_db()?;
        let result = Entity::delete_many()
            .filter(Column::Id.is_in(ids.clone()))
            .exec(&db)
            .await?;
        Ok(result)
    }

    pub async fn update(&self, model: Model) -> anyhow::Result<Model> {
        let db = self.write_db()?;
        let active: ActiveModel = model.into_active_model();
        let updated = active.update(&db).await?;
        Ok(updated)
    }

    pub async fn delete_by_id(&self, id: i64) -> anyhow::Result<DeleteResult> {
        let db = self.write_db()?;
        let delete_key = id;
        let result = Entity::delete_by_id(delete_key).exec(&db).await?;
        Ok(result)
    }
}
